installer-gui-script.script:
function thisMacCanRunIt() {
    if (system.compareVersions(system.version.ProductVersion, '11.0') < 0) {
        my.result.type = 'Fatal';
        my.result.title = 'LogAnalyser needs macOS 11 Big Sur or later';
        my.result.message = 'This Mac has macOS ' + system.version.ProductVersion + '. Update macOS (Apple menu > System Preferences > Software Update), then run this installer again.';
        return false;
    }
    if (system.sysctl('hw.optional.arm64') != 1) {
        my.result.type = 'Fatal';
        my.result.title = 'LogAnalyser needs a Mac with Apple silicon';
        my.result.message = 'This version runs on Macs with an M1, M2, M3 or M4 chip. This Mac has an Intel processor. Ask whoever gave you LogAnalyser for the Intel version.';
        return false;
    }
    return true;
}

function enoughSpace() {
    var neededMB = 300;
    if (my.target.availableKilobytes < neededMB * 1024) {
        my.result.type = 'Fatal';
        my.result.title = 'Not enough disk space';
        my.result.message = 'LogAnalyser needs about ' + neededMB + ' MB, but this disk has only ' + Math.floor(my.target.availableKilobytes / 1024) + ' MB free. Free up some space, then try again.';
        return false;
    }
    return true;
}
